const req = $('Normalize Analysis Request1').first().json;
const ctx = $('Load Dataset Context1').first().json;

const columns = Array.isArray(ctx.columns) ? ctx.columns : [];
const metrics = Array.isArray(ctx.metrics) ? ctx.metrics : [];

const columnLines = columns.map(c =>
  `- ${c.column_name} | type=${c.detected_type ?? 'unknown'} | role=${c.semantic_role ?? 'unknown'} | meaning=${c.business_meaning ?? ''}`
).join('\n');

const metricLines = metrics.map(m =>
  `- ${m.name}: ${m.description ?? m.label ?? ''} | aggregation=${m.aggregation ?? ''} | expression=${m.expression ?? ''}`
).join('\n');

const plannerPrompt = `
You are the SQL planning layer for AnalyzerOS.

User question:
${req.question}

Dataset domain:
${ctx.domain ?? 'unknown'}

Dataset grain:
${ctx.grain_description ?? 'unknown'}

Available cleaned columns:
${columnLines}

Approved/suggested metrics:
${metricLines}

Return ONLY JSON:
{
  "analysis_type": "overview|metric|trend|segment|comparison|anomaly",
  "sql": "SELECT ...",
  "reason": "short explanation"
}

STRICT SQL RULES:
1. PostgreSQL SELECT or WITH only.
2. Query ONLY public.dealos_dataset_rows.
3. Dataset values are in clean_data JSONB.
4. Do NOT include any dataset_id filter. The backend injects it.
5. Never use INSERT, UPDATE, DELETE, DROP, ALTER, CREATE, TRUNCATE, COPY, GRANT, REVOKE.
6. Never SELECT *.
7. Keep result sets compact, generally <= 100 rows.
8. Use NULLIF(...,'') before numeric casts.
9. Use only the real cleaned column names listed above.
10. For an overview, return one compact query with several useful aggregate values where possible.
`;

return [{json:{...req,dataset_context:ctx,planner_prompt:plannerPrompt}}];

const raw = $json.output ?? $json.text ?? $json.response ?? $json;
let plan = raw;
if (typeof raw === 'string') {
  const cleaned = raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'');
  plan = JSON.parse(cleaned);
}
if (!plan.sql || typeof plan.sql !== 'string') throw new Error('Planner response missing sql');
return [{json:{...$('Build SQL Planner Input').first().json,analysis_plan:plan}}];

const item = $json;
let sql = String(item.analysis_plan?.sql ?? '').trim().replace(/;+\s*$/g,'');

if (!/^(select|with)\b/i.test(sql)) throw new Error('Only SELECT or WITH queries are allowed');
if (/\b(insert|update|delete|drop|alter|create|truncate|copy|grant|revoke|merge|call|do)\b/i.test(sql)) {
  throw new Error('Unsafe SQL keyword detected');
}
if (!/\bpublic\.dealos_dataset_rows\b/i.test(sql)) throw new Error('Query must use public.dealos_dataset_rows');
if (/\bdataset_id\b/i.test(sql)) throw new Error('Planner must not supply dataset_id filtering');

sql = sql.replace(
  /\bpublic\.dealos_dataset_rows\b/gi,
  `(SELECT row_number, raw_data, clean_data
    FROM public.dealos_dataset_rows
    WHERE dataset_id = $1::uuid) AS dataset_rows`
);

sql = sql.replace(/AS dataset_rows\s+AS\s+/gi, 'AS dataset_rows ');

return [{json:{...item,safe_sql:sql,dataset_id:item.dataset_id}}];

const req = $('Normalize Analysis Request1').first().json;
const ctx = $('Load Dataset Context1').first().json;
