if(!Number.isFinite(limit)) limit=50;
limit=Math.max(1,Math.min(100,Math.floor(limit)));
return [{json:{dataset_id:datasetId,limit}}];

const req=$('Normalize Sample Request').first().json;
const rows=$input.all().map(i=>({row_number:i.json.row_number,...((i.json.clean_data&&typeof i.json.clean_data==='object')?i.json.clean_data:{})}));
return [{json:{success:true,dataset_id:req.dataset_id,rows,count:rows.length}}];

const b = $json.body ?? $json;
const question = String(b.question ?? '').trim();
const datasetId = String(b.dataset_id ?? '').trim();
const sessionId = String(b.session_id ?? `session-${Date.now()}`);

if (!question) throw new Error('question is required');
if (!datasetId) throw new Error('dataset_id is required');
if (!/^[0-9a-fA-F-]{36}$/.test(datasetId)) throw new Error('dataset_id must be a UUID');

return [{
  json: {
    question,
    dataset_id: datasetId,
    session_id: sessionId,
    organization_id: b.organization_id ?? null,
    user_id: b.user_id ?? null
  }
}];

const raw=$json.output ?? $json.text ?? $json.response ?? $json;
let result=raw;
if(typeof raw==='string'){
  const cleaned=raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'');
  result=JSON.parse(cleaned);
}
const evidence=$('Build Evidence Context').first().json;
result.success=true;
result.dataset_id=evidence.dataset_id;
result.original_question=evidence.question;
result.query_results=evidence.query_results;
result.evidence_available=evidence.evidence_available;
return [{json:result}];
